Three sound events last 5 ms, 40 ms and 800 ms. The letter 'K' is printed for short interference, 'A' for a clap and 'U' for a long sound. What does this code print?

```
void setup() {
  Serial.begin(9600);
  unsigned long sureler[] = {5, 40, 800};
  for (int i = 0; i < 3; i++) {
    char tur;
    if (sureler[i] < 10) tur = 'K';
    else if (sureler[i] > 500) tur = 'U';
    else tur = 'A';
    Serial.print(tur);
  }
}
```

